'use strict';
/* Explicit prototype catalogue. No real product discovery or environment connection. */
window.Explorer=(()=>{
  const A=window.Artemis,copy=A.clone;
  const products=[
    {id:'collab-demo',name:'协作空间',sample:true,environments:[{id:'Staging',platforms:['Android','iOS']},{id:'Test',platforms:['Android','iOS']}]},
    {id:'portal-demo',name:'客户门户',sample:true,environments:[{id:'Dev',platforms:['Android']},{id:'Sandbox',platforms:['Android']}]}
  ];
  const catalogue=[
    {id:'pixel-8',name:'Pixel 8',platform:'Android',detail:'Android 15 · 在线',state:'ready'},
    {id:'android-emulator',name:'Android Emulator',platform:'Android',detail:'Android 15 · 模拟器',state:'ready'},
    {id:'galaxy-s24',name:'Galaxy S24',platform:'Android',detail:'Android 14 · 未连接',state:'offline'},
    {id:'iphone-17',name:'iPhone 17',platform:'iOS',detail:'iOS 26 · 在线',state:'ready'},
    {id:'iphone-16',name:'iPhone 16',platform:'iOS',detail:'iOS 18 · 其他任务占用',state:'busy'}
  ];
  const empty=()=>({productId:'',environment:'',platform:''});
  function valid(x){const p=products.find(p=>p.id===x?.productId);return !!p?.environments.find(e=>e.id===x.environment)?.platforms.includes(x.platform);}
  function config(x){const p=products.find(p=>p.id===x.productId);return {...copy(A.defaults),productId:x.productId,appName:p?.name||'',environment:x.environment,platform:x.platform};}
  function context(x){return {productId:x?.productId||'',environment:x?.environment||'',platform:x?.platform||''};}
  const state=A.data.explorer||={version:1,lastContext:empty(),draft:{text:'',context:empty()},views:{},collapsed:false};
  state.views||={};state.draft||={text:'',context:valid(state.lastContext)?copy(state.lastContext):empty()};
  function save(){A.save();}
  function draft(c){if(!c)return state.draft;if(!c.explorationDraft)c.explorationDraft={text:A.runsFor(c.id).length?'':c.objective||'',context:valid(c.config)?context(c.config):valid(state.lastContext)?copy(state.lastContext):empty()};return c.explorationDraft;}
  function setContext(c,key,value){const d=c?.pending?{context:context(c.pending.snapshot.config)}:draft(c),next=copy(d.context),previous=copy(next);next[key]=value;const p=products.find(p=>p.id===next.productId);if(!p)Object.assign(next,empty());else{let env=p.environments.find(e=>e.id===next.environment);if(!env){env=p.environments[0];next.environment=env.id;}if(!env.platforms.includes(next.platform))next.platform=env.platforms[0];}if(c&&A.active(c.id))return null;if(c?.pending){c.pending.snapshot.config=config(next);c.pending.deviceId=null;c.pending.deviceRevision=(c.pending.deviceRevision||0)+1;draft(c).context=copy(next);}else d.context=next;if(valid(next))state.lastContext=copy(next);save();return {next,adjusted:previous.environment!==next.environment&&key!=='environment'||previous.platform!==next.platform&&key!=='platform'};}
  function candidates(pending){if(!pending)return [];const ctx=pending.snapshot.config;if(!valid(ctx))return [];return catalogue.filter(d=>d.platform===ctx.platform).map(d=>{let status=ctx.environment==='Sandbox'?'offline':d.state;if(status==='ready'&&A.data.runs.some(r=>A.active(r.caseId)?.id===r.id&&r.deviceId===d.id))status='busy';return {...d,state:status};});}
  function submit(c,text){text=text.trim();const d=draft(c);if(!text||!valid(d.context)||c&&(c.archived||A.active(c.id)||c.pending))return null;const cfg=config(d.context);if(!c)c=A.saveCase({name:text.split(/[。！？\n]/)[0].slice(0,36)||'新的探索',objective:text,description:'',module:'未分类',tags:[],config:cfg});else{c.objective=text;c.config=cfg;c.updated=Date.now();c.revision++;}c.pending={id:'intent-'+c.id+'-'+Date.now(),at:Date.now(),text,snapshot:copy({...c,pending:null,explorationDraft:undefined}),deviceId:null,deviceRevision:0};c.explorationDraft={text:'',context:copy(d.context)};c.lastUsed=Date.now();state.lastContext=copy(d.context);if(d===state.draft)state.draft={text:'',context:copy(d.context)};save();return c;}
  function buildPlan(r){const names=['打开登录页','输入邮箱','进入密码页','完成登录','验证首页'];return {title:'邮箱登录探索',type:'task-plan',source:'原型演示数据，非真实 Agent 输出',status:r.status==='passed'?'completed':A.active(r.caseId)?.id===r.id?'active':r.status,description:r.intent?.text||r.snapshot.objective,tasks:[{id:'prepare',title:'准备登录',type:'group',children:[0,1].map(i=>({id:'task-'+i,title:names[i],status:r.steps[i].status,checks:[r.steps[i].expected],eventIds:r.steps[i].events.filter(e=>e.type==='validation').map(e=>e.id)}))},{id:'authenticate',title:'进入密码页并完成登录',type:'group',children:[{id:'task-2',title:names[2],status:r.steps[2].status,type:'bounded-loop',maxAttempts:2,exitWhen:'密码输入框可见',steps:['点击下一步','检查页面是否变化','必要时等待并重试'],assertions:[{title:'密码输入框可见',status:r.steps[2].status}],eventIds:r.steps[2].events.filter(e=>e.type==='validation').map(e=>e.id)},{id:'task-3',title:names[3],status:r.steps[3].status,checks:['登录会话存在'],eventIds:r.steps[3].events.filter(e=>e.type==='validation').map(e=>e.id)}]},{id:'task-4',title:names[4],type:'assertion',status:r.steps[4].status,checks:['首页可见','当前账号与本次登录一致'],eventIds:r.steps[4].events.filter(e=>e.type==='validation').map(e=>e.id)}],adjustments:copy(r.adjustments)};}
  function decorate(r,index){if(r.custom)return;const step=r.steps[index===6?2:Math.max(0,r.current)];if(index===2||index===6){const id=r.id+'-demo-call-'+index;if(!step.events.some(e=>e.id===id))step.events.push({id,at:Date.now()-1,type:'model-output',source:'demo-fixture',text:index===2?'【模拟输出】登录页已显示邮箱输入框。下一步输入测试邮箱，然后检查输入结果。':'【模拟输出】首次点击后仍在邮箱页，密码输入框尚未出现。下一步等待页面稳定，再尝试一次；若仍未进入，则保留失败证据。',callId:id,decisionFrame:index===2?'empty':'email',tool:'明确标记的模拟调用记录。未连接真实模型；输入截图为配套演示帧。',step:r.current});}
    r.taskPlan=buildPlan(r);if(!r.planVersions)r.planVersions=[];if(index===0||index===6||!A.active(r.caseId)){r.planVersions.push({id:'plan-'+r.cursor,title:index===6?'调整：增加等待和一次重试':index===0?'初始计划':'结束时计划',at:Date.now(),content:copy(r.taskPlan)});}save();}
  function start(c,deviceId){const p=c?.pending,d=candidates(p).find(x=>x.id===deviceId);if(!p||!d||d.state!=='ready'||A.active(c.id))return null;const definition=copy(p.snapshot);definition.objective=p.text;definition.scenario=/邮箱/.test(p.text)&&/登录/.test(p.text)?'email-login':'custom';const cfg={...config(context(definition.config)),device:d.name+' · '+d.platform};const r=A.start(definition,cfg);r.intent={id:p.id,at:p.at,text:p.text};r.deviceId=d.id;r.deviceSelection={name:d.name,platform:d.platform,confirmedAt:Date.now()};r.sample=true;r.planVersions=[];if(!r.custom){r.taskPlan=buildPlan(r);r.planVersions.push({id:'initial',title:'初始计划 · 模拟',at:Date.now(),content:copy(r.taskPlan)});}c.pending=null;c.lastUsed=Date.now();save();return r;}
  function tick(r,manual=false){const index=r.cursor;A.advance(r,manual);if(r.cursor!==index)decorate(r,index);}
  function stop(r){A.stop(r);if(!r.custom){r.taskPlan=buildPlan(r);r.planVersions||=[];r.planVersions.push({id:'stopped-'+r.ended,title:'停止时计划',at:r.ended,content:copy(r.taskPlan)});}save();}
  function touch(c){if(c){c.lastUsed=Date.now();save();}}
  // Add a labelled demonstration, without changing pre-existing history snapshots.
  if(!state.fixtureAdded){const ctx={productId:'collab-demo',environment:'Staging',platform:'Android'};const c=A.saveCase({name:'探索邮箱登录与异常恢复',objective:'探索邮箱登录流程，验证首页并观察异常恢复',description:'交互演示 Case，所有运行和画面均为模拟。',module:'未分类',tags:[],config:config(ctx)});c.explorationDraft={text:'',context:ctx};for(let n=0;n<2;n++){c.explorationDraft.text=c.objective;submit(c,c.objective);const r=start(c,n?'android-emulator':'pixel-8');for(let i=0;i<(n?12:6);i++)tick(r,true);if(!n)stop(r);}state.fixtureAdded=true;state.lastContext=empty();state.draft={text:'',context:empty()};save();}
  return {state,products,catalogue,valid,context,config,empty,draft,setContext,candidates,submit,start,tick,stop,touch,save};
})();
